--吕布每累计受到超过自身最大生命值10%的伤害，便会为自身恢复50点内力，且每场战斗一次，当吕布受到致命伤害时，会使自身无敌2秒，并立即恢复300点内力
--每场战斗一次，当吕布受到致命伤害时，会立即震慑所有敌人眩晕2秒，吕布所有攻击无视对方50%防御，持续8秒
---@class W_LvB_skill1_1_Model : SkillFeatures_Model @
---@field super SkillFeatures_Model @SkillFeatures_Model
local M = class("W_LvB_skill1_1_Model", SkillFeatures_Model)

function M:init(ply, skill,className)
    M.super.init(self, ply, skill,className)
    self.triggerHpRate = self:getParam(1)  -- 触发的生命值比例
    self.addAngerBuff = self:getParam(2) --恢复内力
    self.buffId1 = self:getParam(3)--无敌回内
    self.buffId2 = self:getParam(4, 0)--震慑加无视防御
    self.def_per = self:getParam(5, 0)--五十防御百分比
    self.interval = self:getParam(6, 0)--持续8秒
    self.oldTotalLostHp = 0  -- 按比例累计损失血量
    self.lost_hp_num = 0
    self.hp_max = 0
    self.deadNums = 0
    self.max_add_nums = 10 --一帧中受到的伤害恢复内力的最大次数
    self.is_no_def = false --无视敌方防御
    self.is_dead_now = false --
    EventDispatcher:registerEvent("injure", {self,self.injureHandler})
end

function M:spawn()
    M.super.spawn(self)
    self.skill3 = nil
    ---@type PlayerSkillItem
    local skill3 = self.player.plySkill:getSkillByName("skill3")
    if skill3 ~= nil then
        ---@type SkillDataConfig
        self.skill3 = skill3.cur_skill_config.feature
    end
end

function M:spawnFinish()
    self.hp_max = self.player.data:get_hp() -- 获取血量上限
    self.lost_hp_num = GlobalTools:Mul(self.hp_max, self.triggerHpRate) -- 每层每次损失的血量
end

function M:update(dt,unsdt)
    M.super.update(self, dt, unsdt)
    if self.skill3 and self.skill3.alreadyAdd then
    elseif not self.is_dead_now and self.lost_hp_num and self.lost_hp_num ~= 0 and self.player.totalLostHp and self.player.totalLostHp > 0 and self.oldTotalLostHp ~= self.player.totalLostHp then
        local hp_max = self.hp_max -- 获取血量上限
        local lastTotalLostHp = self.player.totalLostHp or 0 -- 累计损失血量
        local lostRate = GlobalTools:Div((lastTotalLostHp - self.oldTotalLostHp),hp_max) -- (累计损失血量 - 上次累计损失血量 ) / 血量上限 = 当前损失血量的比例
        local curAddBuffNum = GlobalTools:Div(lostRate, self.triggerHpRate) -- (当前损失血量的比例 / 每累积损失多少加一层) = 要加多少层
        local num = math.floor(GlobalTools:ToFloat(curAddBuffNum)) -- 定点数转浮点数
        local real_num = num
        if num > self.max_add_nums then
            num = self.max_add_nums
        end
        if num > 0 then
            self.oldTotalLostHp = self.oldTotalLostHp + GlobalTools:Mul(self.lost_hp_num, GlobalTools:ToFix(real_num))
            for i = 1, num do
                self.player.bufMgr:addBufById(self.addAngerBuff, self.player, self.skill)
                --self.player.data:addAnger(self.addAngerValue)
            end
        end
    end
end

function M:injureHandler(eventName, eventData)
    if self.is_no_def and self.player:equal(eventData.killer) and self.def_per > 0 then
        -- 无视敌方防御
        local def = eventData.victim.data.def:getValue()
        def = GlobalTools:Mul(def, self.def_per)
        eventData.victim.data.def:addToAddListTemp(-def) -- 将防御将至
    end
end

function M:dead(data)
    M.super.dead(self)
    if self.deadNums < 1 then
        self.deadNums = 1
        self.player.data:set_curHp(GlobalTools.base1)
        self.player.bufMgr:addBufById(self.buffId1, self.player)
        if self.buffId2 and self.buffId2 > 0 then
            local targets = SelectTargetUtil:findPlayerByParam(self.player, {camp = "enemy"})
            for i = 1, targets.Count do
                local ply = targets:get(i-1)    
                if ply and ply.master == nil then
                    ply.bufMgr:addBufById(self.buffId2, self.player)
                end
            end
            if self.interval > 0 then
                self.is_no_def = true
                TimeTools:delayTime(self.interval, function()
                    self.is_no_def = false
                end)
            end
        end
        return false
    end
    self.is_dead_now = true
    return true
end

function M:destroy()
    M.super.destroy(self)
    EventDispatcher:unRegisterEvent("injure", {self,self.injureHandler})
end
return M